from __future__ import annotations

import base64
import hashlib
import json
import zlib

COHORT_SHA256 = "002b4239d6ab5a981cc2d3921232daaa4533f38224c6e104d2d26e5a0d11c562"
MUTATIONS_SHA256 = "924691ac1e896ab1ec0dc3cd8f64633a4c7548ade1ec22daac2fa386ecb5e6ab"

_COHORT_B64 = """"""
_MUTATIONS_B64 = """eNqV1D8LwjAQh+G9nyJkbqG//q+bDs7iKlKiptBBK22dSr+7sVBE0PNuuSF35Nne0VNKXx+DGZr2Vt1N0/V6pQ7uValxnm5v6sF21dn0tmoubq23+2AXIthofzk52brt7Jeb9fvm9fvHUs+byedoEUOLKC2SaDFDiyktlmgJQ0soLZFoKUNLKS2VaBlDyygtk2g5Q8spLZdoBUMrKK2QaCVDKymtFGgI/2vu5reGUKIxWgKqJZC0BIyWgGoJJC0BoyWgWgJJS8BoCaiWYGmJm0dv8p5mPXw3"""

def _decode(payload: str, expected_sha: str):
    raw = zlib.decompress(base64.b64decode(payload.encode("ascii")))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != expected_sha:
        raise RuntimeError(f"sealed payload hash mismatch: {actual} != {expected_sha}")
    return json.loads(raw)

def load_cohort():
    return _decode(_COHORT_B64, COHORT_SHA256)

def load_mutations():
    return _decode(_MUTATIONS_B64, MUTATIONS_SHA256)
